using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using NUnit.Framework;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using Object = UnityEngine.Object;

namespace UnityBox.AvatarSecuritySystem.Tests
{
    public sealed class LegacyComponentMigrationTests
    {
        // Both GUIDs were actually generated by Unity when importing the old,
        // metadata-free published package into separate projects.
        private const string LegacyCoreGuid = "70959987f069e36d39b8a69869eef7f5";
        private const string LegacyVrcGuid = "3e5abd52463ea35e495d077153f8849e";
        private const string UnrelatedMissingGuid = "c127e5a3d9ac4f15a9693379190ea133";
        private string folder;
        private SceneSetup[] previousScenes;
        private AudioClip warning;
        private AudioClip success;
        private IDisposable automaticRepairSuspension;

        [SetUp]
        public void SetUp()
        {
            automaticRepairSuspension = LegacyComponentMigration.SuspendAutomaticRepair();
            previousScenes = EditorSceneManager.GetSceneManagerSetup();
            EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            folder = "Assets/__ASSLegacyMigration_" + Guid.NewGuid().ToString("N");
            AssetDatabase.CreateFolder("Assets", folder.Substring(7));
            warning = Resources.Load<AudioClip>("CountdownWarning");
            success = Resources.Load<AudioClip>("PasswordSuccess");
            Assert.That(warning, Is.Not.Null);
            Assert.That(success, Is.Not.Null);
            Assert.That(AssetDatabase.GUIDToAssetPath(LegacyCoreGuid), Is.Empty);
            Assert.That(AssetDatabase.GUIDToAssetPath(LegacyVrcGuid), Is.Empty);
        }

        [TearDown]
        public void TearDown()
        {
            if (previousScenes.Length == 0 || previousScenes.All(item => string.IsNullOrEmpty(item.path)))
                EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);
            else
                EditorSceneManager.RestoreSceneManagerSetup(previousScenes);
            AssetDatabase.DeleteAsset(folder);
            automaticRepairSuspension.Dispose();
        }

        [TestCase(LegacyCoreGuid)]
        [TestCase(LegacyVrcGuid)]
        public void SavedLegacySceneRecoversItsOriginalConfigurationAndLeavesOtherMissingScripts(string legacyGuid)
        {
            var root = CreateConfigured("LegacySceneAvatar");
            var unrelated = new GameObject("UnrelatedMissing");
            unrelated.transform.SetParent(root.transform, false);
            var input = unrelated.AddComponent<StandaloneSecurityInput>();
            string inputGuid = ScriptGuid(input);
            string path = folder + "/LegacyScene.unity";
            Assert.That(EditorSceneManager.SaveScene(root.scene, path), Is.True);
            string original = File.ReadAllText(path);
            string componentId = ComponentId(original, LegacyComponentMigration.CanonicalGuid);
            string assetGuid = AssetDatabase.AssetPathToGUID(path);
            CloseFixtureScene();
            string legacy = original.Replace(LegacyComponentMigration.CanonicalGuid, legacyGuid)
                .Replace(inputGuid, UnrelatedMissingGuid);
            File.WriteAllText(path, legacy);
            Import(path);
            var loaded = EditorSceneManager.OpenScene(path, OpenSceneMode.Single);
            var broken = Root(loaded, "LegacySceneAvatar");
            Assert.That(broken.GetComponent<ASSComponent>(), Is.Null);
            Assert.That(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(broken), Is.EqualTo(1));
            Assert.That(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(broken.transform.GetChild(0).gameObject), Is.EqualTo(1));
            Assert.That(loaded.isDirty, Is.False);

            var result = LegacyComponentMigration.RepairAssets(new[] { path });

            Assert.That(result.RepairedComponents, Is.EqualTo(1));
            Assert.That(result.ChangedAssets, Does.Contain(path));
            AssertOriginalBackup(result.BackupDirectory, System.Text.Encoding.UTF8.GetBytes(legacy));
            Assert.That(AssetDatabase.AssetPathToGUID(path), Is.EqualTo(assetGuid));
            Assert.That(File.ReadAllText(path), Is.EqualTo(legacy.Replace(legacyGuid, LegacyComponentMigration.CanonicalGuid)));
            Assert.That(ComponentId(File.ReadAllText(path), LegacyComponentMigration.CanonicalGuid), Is.EqualTo(componentId));
            var restored = Root(SceneManager.GetActiveScene(), "LegacySceneAvatar");
            AssertConfiguration(restored.GetComponent<ASSComponent>());
            Assert.That(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(restored), Is.Zero);
            Assert.That(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(restored.transform.GetChild(0).gameObject), Is.EqualTo(1));
            Assert.That(File.ReadAllText(path), Does.Contain(UnrelatedMissingGuid));
            Assert.That(LegacyComponentMigration.RepairAssets(new[] { path }).RepairedComponents, Is.Zero);
        }

        [TestCase(LegacyCoreGuid)]
        [TestCase(LegacyVrcGuid)]
        public void SavedLegacyPrefabRecoversWithoutChangingItsAssetOrComponentIdentity(string legacyGuid)
        {
            var root = CreateConfigured("LegacyPrefabAvatar");
            string path = folder + "/LegacyPrefab.prefab";
            PrefabUtility.SaveAsPrefabAsset(root, path);
            string original = File.ReadAllText(path);
            string componentId = ComponentId(original, LegacyComponentMigration.CanonicalGuid);
            string assetGuid = AssetDatabase.AssetPathToGUID(path);
            Object.DestroyImmediate(root);
            string legacy = original.Replace(LegacyComponentMigration.CanonicalGuid, legacyGuid);
            File.WriteAllText(path, legacy);
            Import(path);
            var broken = PrefabUtility.LoadPrefabContents(path);
            try
            {
                Assert.That(broken.GetComponent<ASSComponent>(), Is.Null);
                Assert.That(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(broken), Is.EqualTo(1));
            }
            finally { PrefabUtility.UnloadPrefabContents(broken); }

            var result = LegacyComponentMigration.RepairAssets(new[] { path });

            Assert.That(result.RepairedComponents, Is.EqualTo(1));
            Assert.That(result.ChangedAssets, Does.Contain(path));
            AssertOriginalBackup(result.BackupDirectory, System.Text.Encoding.UTF8.GetBytes(legacy));
            Assert.That(AssetDatabase.AssetPathToGUID(path), Is.EqualTo(assetGuid));
            Assert.That(File.ReadAllText(path), Is.EqualTo(original));
            Assert.That(ComponentId(File.ReadAllText(path), LegacyComponentMigration.CanonicalGuid), Is.EqualTo(componentId));
            var loaded = PrefabUtility.LoadPrefabContents(path);
            try
            {
                AssertConfiguration(loaded.GetComponent<ASSComponent>());
                Assert.That(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(loaded), Is.Zero);
            }
            finally { PrefabUtility.UnloadPrefabContents(loaded); }
            Assert.That(LegacyComponentMigration.RepairAssets(new[] { path }).RepairedComponents, Is.Zero);
        }

        [Test]
        public void RestoringThePrefabDefinitionKeepsExistingInstanceOverrides()
        {
            string prefabPath = folder + "/Base.prefab";
            var source = CreateConfigured("PrefabWithOverrides");
            var asset = PrefabUtility.SaveAsPrefabAsset(source, prefabPath);
            Object.DestroyImmediate(source);
            var instance = (GameObject)PrefabUtility.InstantiatePrefab(asset);
            string instanceName = instance.name;
            var config = instance.GetComponent<ASSComponent>();
            config.gesturePassword = new List<int> { 0, 6, 7 };
            config.useRightHand = false;
            config.countdownDuration = 23.5f;
            PrefabUtility.RecordPrefabInstancePropertyModifications(config);
            Assert.That(PrefabUtility.GetPropertyModifications(instance).Any(item => item.propertyPath.StartsWith("gesturePassword", StringComparison.Ordinal)), Is.True);
            string scenePath = folder + "/Overrides.unity";
            Assert.That(EditorSceneManager.SaveScene(instance.scene, scenePath), Is.True);
            string originalScene = File.ReadAllText(scenePath);
            string prefabGuid = AssetDatabase.AssetPathToGUID(prefabPath);
            string legacyScene = AddStrippedReference(originalScene, File.ReadAllText(prefabPath), prefabGuid, LegacyCoreGuid);
            CloseFixtureScene();
            File.WriteAllText(prefabPath, File.ReadAllText(prefabPath)
                .Replace(LegacyComponentMigration.CanonicalGuid, LegacyCoreGuid));
            Import(prefabPath);
            File.WriteAllText(scenePath, legacyScene);
            Import(scenePath);
            var scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
            Assert.That(Root(scene, instanceName).GetComponent<ASSComponent>(), Is.Null);

            var result = LegacyComponentMigration.RepairAssets(new[] { prefabPath, scenePath });

            Assert.That(result.RepairedComponents, Is.EqualTo(2));
            Assert.That(AssetDatabase.AssetPathToGUID(prefabPath), Is.EqualTo(prefabGuid));
            Assert.That(File.ReadAllText(scenePath), Is.EqualTo(legacyScene.Replace(LegacyCoreGuid, LegacyComponentMigration.CanonicalGuid)));
            scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
            config = Root(scene, instanceName).GetComponent<ASSComponent>();
            Assert.That(config, Is.Not.Null);
            Assert.That(config.gesturePassword, Is.EqualTo(new[] { 0, 6, 7 }));
            Assert.That(config.useRightHand, Is.False);
            Assert.That(config.countdownDuration, Is.EqualTo(23.5f));
            Assert.That(config.warningBeep, Is.SameAs(warning));
            Assert.That(config.successSound, Is.SameAs(success));
            Assert.That(PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(config.gameObject), Is.EqualTo(prefabPath));
            Assert.That(config.gameObject.GetComponents<ASSComponent>(), Has.Length.EqualTo(1));
        }

        [Test]
        public void AConfirmedFullDefinitionAlsoRestoresItsStrippedYamlReference()
        {
            string path = folder + "/Definition.prefab";
            var asset = PrefabUtility.SaveAsPrefabAsset(CreateConfigured("Definition"), path);
            string yaml = File.ReadAllText(path);
            string stripped = StrippedReference(ComponentId(yaml, LegacyComponentMigration.CanonicalGuid),
                AssetDatabase.AssetPathToGUID(path), "42", LegacyCoreGuid);
            string legacy = yaml.Replace(LegacyComponentMigration.CanonicalGuid, LegacyCoreGuid) + stripped;

            Assert.That(LegacyComponentMigration.TryMigrateYaml(legacy, _ => false, out var restored, out int count), Is.True);
            Assert.That(count, Is.EqualTo(2));
            Assert.That(restored, Is.EqualTo(legacy.Replace(LegacyCoreGuid, LegacyComponentMigration.CanonicalGuid)));
            Assert.That(asset, Is.Not.Null);
        }

        [Test]
        public void PersistedLegacyIdentityRestoresAStrippedSceneImportedAfterItsPrefab()
        {
            string legacyGuid = Guid.NewGuid().ToString("N");
            string prefabPath = folder + "/PreviouslyRepaired.prefab";
            var source = CreateConfigured("PreviouslyRepaired");
            var asset = PrefabUtility.SaveAsPrefabAsset(source, prefabPath);
            Object.DestroyImmediate(source);
            var instance = (GameObject)PrefabUtility.InstantiatePrefab(asset);
            string instanceName = instance.name;
            var config = instance.GetComponent<ASSComponent>();
            config.countdownDuration = 22f;
            PrefabUtility.RecordPrefabInstancePropertyModifications(config);
            string scenePath = folder + "/LaterImported.unity";
            Assert.That(EditorSceneManager.SaveScene(instance.scene, scenePath), Is.True);
            string originalPrefab = File.ReadAllText(prefabPath);
            string prefabGuid = AssetDatabase.AssetPathToGUID(prefabPath);
            string legacyScene = AddStrippedReference(File.ReadAllText(scenePath), originalPrefab, prefabGuid, legacyGuid);
            string sceneGuid = AssetDatabase.AssetPathToGUID(scenePath);
            CloseFixtureScene();
            File.WriteAllText(prefabPath, originalPrefab.Replace(LegacyComponentMigration.CanonicalGuid, legacyGuid));
            Import(prefabPath);

            Assert.That(LegacyComponentMigration.RepairAssets(new[] { prefabPath }).RepairedComponents, Is.EqualTo(1));
            string aliasesPath = Path.GetFullPath("UserSettings/UnityBox/ASSMigration/LegacyGuids.json");
            Assert.That(File.ReadAllText(aliasesPath), Does.Contain(legacyGuid));
            // RepairAssets reads the persisted identity map for each invocation;
            // this later asset contains no full configuration to rediscover it.
            File.WriteAllText(scenePath, legacyScene);
            Import(scenePath);

            var result = LegacyComponentMigration.RepairAssets(new[] { scenePath });

            Assert.That(result.RepairedComponents, Is.EqualTo(1));
            Assert.That(AssetDatabase.AssetPathToGUID(scenePath), Is.EqualTo(sceneGuid));
            Assert.That(File.ReadAllText(scenePath), Is.EqualTo(legacyScene.Replace(legacyGuid, LegacyComponentMigration.CanonicalGuid)));
            var scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
            config = Root(scene, instanceName).GetComponent<ASSComponent>();
            Assert.That(config, Is.Not.Null);
            Assert.That(config.countdownDuration, Is.EqualTo(22f));
            Assert.That(config.gesturePassword, Is.EqualTo(new[] { 7, 0, 6, 2, 2 }));
            Assert.That(config.warningBeep, Is.SameAs(warning));
            Assert.That(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(config.gameObject), Is.Zero);
        }

        [Test]
        public void GuidReplacementPreservesBomCrLfAndEveryOtherYamlCharacter()
        {
            string path = folder + "/Text.prefab";
            PrefabUtility.SaveAsPrefabAsset(CreateConfigured("TextAvatar"), path);
            string original = File.ReadAllText(path).Replace("\r\n", "\n").Replace("\n", "\r\n");
            string legacy = "\uFEFF" + original.Replace(LegacyComponentMigration.CanonicalGuid, LegacyCoreGuid);

            Assert.That(LegacyComponentMigration.TryMigrateYaml(legacy, _ => false, out var migrated, out int count), Is.True);
            Assert.That(count, Is.EqualTo(1));
            Assert.That(migrated, Is.EqualTo("\uFEFF" + original));
            Assert.That(LegacyComponentMigration.TryMigrateYaml(migrated, _ => false, out var repeated, out count), Is.False);
            Assert.That(count, Is.Zero);
            Assert.That(repeated, Is.EqualTo(migrated));
        }

        [Test]
        public void AnAlreadyResolvedScriptIsNotReassignedFromItsSerializedFields()
        {
            string path = folder + "/Resolved.prefab";
            PrefabUtility.SaveAsPrefabAsset(CreateConfigured("ResolvedAvatar"), path);
            string yaml = File.ReadAllText(path).Replace(LegacyComponentMigration.CanonicalGuid, LegacyCoreGuid);

            Assert.That(LegacyComponentMigration.TryMigrateYaml(yaml, guid => guid == LegacyCoreGuid, out var migrated, out int count), Is.False);
            Assert.That(migrated, Is.EqualTo(yaml));
            Assert.That(count, Is.Zero);
        }

        [Test]
        public void AnUnrelatedMissingComponentWithoutTheAssConfigurationIsUntouched()
        {
            var root = new GameObject("Unrelated");
            var input = root.AddComponent<StandaloneSecurityInput>();
            string guid = ScriptGuid(input);
            string path = folder + "/Unrelated.prefab";
            PrefabUtility.SaveAsPrefabAsset(root, path);
            string yaml = File.ReadAllText(path).Replace(guid, UnrelatedMissingGuid);

            Assert.That(LegacyComponentMigration.TryMigrateYaml(yaml, _ => false, out var migrated, out int count), Is.False);
            Assert.That(migrated, Is.EqualTo(yaml));
            Assert.That(count, Is.Zero);
        }

        [Test]
        public void ADirtyLoadedSceneIsDeferredWithoutDiscardingUnsavedEdits()
        {
            var root = CreateConfigured("DirtyLegacyAvatar");
            string path = folder + "/DirtyScene.unity";
            Assert.That(EditorSceneManager.SaveScene(root.scene, path), Is.True);
            CloseFixtureScene();
            string legacy = File.ReadAllText(path).Replace(LegacyComponentMigration.CanonicalGuid, LegacyCoreGuid);
            File.WriteAllText(path, legacy);
            Import(path);
            var scene = EditorSceneManager.OpenScene(path, OpenSceneMode.Single);
            root = Root(scene, "DirtyLegacyAvatar");
            Assert.That(root.GetComponent<ASSComponent>(), Is.Null);
            root.transform.localPosition = new Vector3(3, 4, 5);
            EditorSceneManager.MarkSceneDirty(scene);

            var result = LegacyComponentMigration.RepairAssets(new[] { path });

            Assert.That(result.RepairedComponents, Is.Zero);
            Assert.That(result.ChangedAssets, Is.Empty);
            Assert.That(result.DeferredAssets, Does.Contain(path));
            Assert.That(File.ReadAllText(path), Is.EqualTo(legacy));
            Assert.That(root, Is.Not.Null);
            Assert.That(root.transform.localPosition, Is.EqualTo(new Vector3(3, 4, 5)));
            Assert.That(scene.isDirty, Is.True);
        }

        [Test]
        public void AForeignExplicitEditorClassIdentifierIsNotTreatedAsAss()
        {
            string path = folder + "/ForeignIdentifier.prefab";
            PrefabUtility.SaveAsPrefabAsset(CreateConfigured("ForeignIdentifier"), path);
            string yaml = File.ReadAllText(path).Replace(LegacyComponentMigration.CanonicalGuid, LegacyCoreGuid);
            yaml = Regex.Replace(yaml, @"(?m)^  m_EditorClassIdentifier:.*$",
                "  m_EditorClassIdentifier: ThirdParty.Runtime::Other.PasswordRecorder");

            Assert.That(LegacyComponentMigration.TryMigrateYaml(yaml, _ => false, out var migrated, out int count), Is.False);
            Assert.That(migrated, Is.EqualTo(yaml));
            Assert.That(count, Is.Zero);
        }

        private GameObject CreateConfigured(string name)
        {
            var root = new GameObject(name);
            var config = root.AddComponent<ASSComponent>();
            config.gesturePassword = new List<int> { 7, 0, 6, 2, 2 };
            config.useRightHand = true;
            config.countdownDuration = 17.5f;
            config.warningThreshold = 4.25f;
            config.gestureHoldTime = 0.42f;
            config.gestureErrorTolerance = 0.17f;
            config.gestureMaxHoldTime = 2.3f;
            config.disableRootChildren = false;
            config.disableOverlay = true;
            config.disableWarningSound = true;
            config.disableObfuscation = true;
            config.enableDecoyLayers = false;
            config.enableDecoyStates = false;
            config.warningBeep = warning;
            config.successSound = success;
            EditorUtility.SetDirty(config);
            return root;
        }

        private void AssertConfiguration(ASSComponent config)
        {
            Assert.That(config, Is.Not.Null);
            Assert.That(config.gesturePassword, Is.EqualTo(new[] { 7, 0, 6, 2, 2 }));
            Assert.That(config.useRightHand, Is.True);
            Assert.That(config.countdownDuration, Is.EqualTo(17.5f));
            Assert.That(config.warningThreshold, Is.EqualTo(4.25f));
            Assert.That(config.gestureHoldTime, Is.EqualTo(0.42f));
            Assert.That(config.gestureErrorTolerance, Is.EqualTo(0.17f));
            Assert.That(config.gestureMaxHoldTime, Is.EqualTo(2.3f));
            Assert.That(config.disableRootChildren, Is.False);
            Assert.That(config.disableOverlay, Is.True);
            Assert.That(config.disableWarningSound, Is.True);
            Assert.That(config.disableObfuscation, Is.True);
            Assert.That(config.enableDecoyLayers, Is.False);
            Assert.That(config.enableDecoyStates, Is.False);
            Assert.That(config.warningBeep, Is.SameAs(warning));
            Assert.That(config.successSound, Is.SameAs(success));
        }

        private static string ScriptGuid(MonoBehaviour component) =>
            AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(MonoScript.FromMonoBehaviour(component)));

        private static GameObject Root(Scene scene, string name) => scene.GetRootGameObjects().Single(item => item.name == name);

        private static void CloseFixtureScene() => EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

        private static void Import(string path) =>
            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport | ImportAssetOptions.ForceUpdate);

        private static string ComponentId(string yaml, string scriptGuid)
        {
            var blocks = Regex.Matches(yaml, @"^--- !u!114 &(-?\d+)(?: stripped)?\r?\n.*?(?=^--- |\z)", RegexOptions.Multiline | RegexOptions.Singleline);
            return blocks.Cast<Match>().Single(item => item.Value.Contains("guid: " + scriptGuid)).Groups[1].Value;
        }

        private static string AddStrippedReference(string sceneYaml, string prefabYaml, string prefabGuid, string legacyGuid)
        {
            if (sceneYaml.Contains("guid: " + LegacyComponentMigration.CanonicalGuid))
                return sceneYaml.Replace(LegacyComponentMigration.CanonicalGuid, legacyGuid);
            string instanceId = Regex.Match(sceneYaml, @"(?m)^--- !u!1001 &(-?\d+)").Groups[1].Value;
            Assert.That(instanceId, Is.Not.Empty);
            return sceneYaml + StrippedReference(ComponentId(prefabYaml, LegacyComponentMigration.CanonicalGuid),
                prefabGuid, instanceId, legacyGuid);
        }

        private static string StrippedReference(string sourceComponentId, string prefabGuid, string instanceId, string scriptGuid) =>
            "\n--- !u!114 &9123276586543210 stripped\nMonoBehaviour:\n"
            + "  m_CorrespondingSourceObject: {fileID: " + sourceComponentId + ", guid: " + prefabGuid + ", type: 3}\n"
            + "  m_PrefabInstance: {fileID: " + instanceId + "}\n  m_PrefabAsset: {fileID: 0}\n"
            + "  m_GameObject: {fileID: 0}\n  m_Enabled: 1\n  m_EditorHideFlags: 0\n"
            + "  m_Script: {fileID: 11500000, guid: " + scriptGuid + ", type: 3}\n"
            + "  m_Name: \n  m_EditorClassIdentifier: \n";

        private static void AssertOriginalBackup(string directory, byte[] original)
        {
            Assert.That(Directory.Exists(directory), Is.True);
            Assert.That(Directory.GetFiles(directory, "*", SearchOption.AllDirectories)
                .Any(path => File.ReadAllBytes(path).SequenceEqual(original)), Is.True, "The original legacy YAML bytes must be backed up before repair.");
        }
    }
}
